799→    searchForm.addEventListener("submit", function (e) {
800→      e.preventDefault();
801→      const input = searchForm.querySelector(".searchTerm").value.trim();
802→      if (!input) return;
803→
804→      const path = "/search/" + encodeURIComponent(input);
805→      loadInPanel(getTargetPanel(), path);
806→    });
807→  }
808→});
